INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (1, 100, 3, "おいしすぎて食べ始めたら\n止まらない最高のプリンなの\n今のミヤコを止められるヤツは\n誰もいないの", 1, "プリンセスなプリンなの\nお店にあったいろんな食べもの\nを入れられるだけ入れてみたの\nどんな味なのか楽しみなの", "ペコリーヌのプリン", "やばいですね☆なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (2, 101, 3, "なんだかすごくやさしい気持ち\nになる味なの…\nおはようからおやすみまで\nずっと一緒な味なの…", 1, "いつもオマエのそばに寄りそう\nヤツのぷりんなの。ミヤコの\nワガママもやさしく受け入れて\nくれそうなの", "コッコロのプリン", "主さま、なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (3, 102, 3, "いろんな味が一度で楽しめる\nプリンなの。ツンデレはプリン\nにするとおいしいの。ミヤコも\nツンデレを目指してみるの", 0, "ツンツンデレデレなヤツの\nプリンなの。砂糖とスパイスを\n混ぜてみたの。どんな味になる\nか楽しみなの", "キャルのプリン", "ぶっ殺すぞ！なの！\n…デレデレはどこなの？", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (4, 103, 3, "あったかいところで食べる\nプリンアイスは最高なの～♪\n安心しすぎて昔の記憶のない\nミヤコも心が子どもになるの～", 1, "オマエと同じで、一度赤ちゃん\nみたいになったヤツのプリン\nなの。ヒンヤリ、プリンアイス\nにしてみたの", "シェフィのプリン", "おにーたん♪なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (5, 104, 3, "トマトで栄養補給も完璧なの\nどんどん力がみなぎってきて\n復活も夢じゃないの\nミヤコが復活したら…", 1, "イリヤを見てたら思いついた\nトマトジュースが隠し味の\nプリンなの。栄養満点なの", "イリヤのプリン", "ハーハッハッハ！\n世界征服なのじゃなのー！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (6, 105, 3, "見た目がかわいくてもミヤコは\n味にも厳しいの。あむっ…\nこ、これは…！なんだかすごく\n変な気分になってきたの…", 1, "アカリのプリンなの。ヨリと\n同じくらいかわいく作って\nやったの。正直ミヤコは\nおいしければなんでもいいの", "アカリのプリン", "お兄ちゃんのエッチ！　なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (7, 106, 3, "んむぅ…これはなかなか感想が\n難しいプリンなの…率直に言い\nたいような…心のうちに秘めて\nおきたいような…", 1, "かわいくつくらないとアカリが\n怒りそうだからヨリのプリンは\nかわいく作ったの。自信作なの", "ヨリのプリン", "えっと…その…あんたのこと…\nだ、大っ嫌いなのーー！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (8, 107, 3, "このプリンを食べるとシノブが\nミヤコの中にいるみたいなの！\nシノブの力があれば未来の\nプリンを見放題なの！", 0, "シノブはいつもミヤコに\nやさしくしてくれるから\n丁寧に作ったの。ドクロ親父は\nいらないから作ってないの", "シノブのプリン", "お父さん…\nいいかげんにしてなの！\nん？プリンの未来は…\n見えなかったの…", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (9, 108, 3, "固すぎてかじれないから丸吞み\nにしたの。なんだか体が硬く\nなった気がするの。みんなを\n守れる気がするの！", 1, "黒い鎧を脱がないヤツのプリン\nなの。固めのプリンを目指したら\nカチカチになりすぎたの", "ジュンのプリン", "インフェルノシールド！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (10, 109, 3, "口の中でスパイスがプチプチ\nはじけて新食感なの！\nプチプチがミヤコを\n翻弄するの！", 1, "オマエをいっつもからかってる\nヤツのプリンなの\nちょっぴり変わったスパイスで\nからかいを表現したの", "トモのプリン", "あなたといると調子が狂うな\n…なの\n翻弄してたのはオマエなの？", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (11, 110, 3, "ん～見かけによらず濃厚な\nパンチのある味わいが\n口いっぱいに広がるの！", 1, "王宮騎士団にいるちっこいヤツ\nなの。ちっこいけどやるヤツ\nらしいから、濃いめの味付けに\nしてみたの", "マツリのプリン", "タイガーヒーローボンバー！\nなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (13, 111, 3, "クールな見た目なのにとっても\n優しい味なの！なんだか\n懐かしさを感じるの…", 1, "なんかすごくクールなプリンなの\nなんかテンションも少し\n低そうなの。これ\n食べちゃっても大丈夫なの？", "クロエのプリン", "ま、いいんじゃん？\nしらんけどなの", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (14, 112, 3, "なんか変わった食感なの…\nちゃる…ちょる…ちぇる？\nちぇるってしてるの\nでもちぇるってなんなの？", 1, "きれいにデコれたの！\nカラフルでおいしそうなの\nこれは期待できそうなの", "チエルのプリン", "ぷりーん★なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (15, 113, 3, "味はなんか妙に\n甘酸っぱいの…\n食べたことない味なの\nこの味ってもしかして…", 1, "見た目は完ぺきなの！\nこれをつくったやつは\nきっと天才なの！\n早く食べたいの！", "ユニのプリン", "端的に換言すれば\n青春の味なの？", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (16, 114, 3, "ミヤコも幽霊になる前の記憶\nがないのに、なんだか懐かしい\n気持ちになってくるの…", 1, "オマエから聞いた懐かしい\n味ってヤツを全部入れてみたの\nオマエ記憶がないのに懐かしい\nってどういうことなの？", "サレンのプリン", "幼なじみはあんた…なの？", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (17, 115, 3, "おかしいの。このプリンを\n食べてから、３回も転んだの\nミヤコは幽霊だから転んだり\nしないの。なんでなの…？", 1, "たまたま会ったメイドに教えて\nもらった作り方なの。メイドは\nプリンも作れるはずなの。\nなのにこの不安は何なの…？", "スズメのプリン", "ひゃああんなの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (18, 116, 3, "甘さのなかに少しのしょっぱさ\nクセになる味なの\nこのプリンはがんばればきっと\nいろんな美味しいになれるの", 0, "怖がりな子どもが教えてくれた\n小さくてかわいいプリンなの　\n触ってないのにぷるぷる震える\n驚きのやわらかさなの", "クルミのプリン", "サルキデバレヤ！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (19, 117, 3, "このプリン、食べるとなんだか\nお姉ちゃんになった気分に\nなるの。ピンチのプリンは\nミヤコが守ってやるの！", 1, "くまのぬいぐるみを見ていたら\nひらめいたの。小さいけど\nしっかりした甘さの元気に\nなれるプリンなの！", "アヤネのプリン", "プリンフルスイングなの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (20, 118, 3, "メルヘンパワーがあふれてきて\nいまならミヤコにも魔法が\n使える気がするの！\nほな、いきまひょ～なの！", 1, "マホマホ王国って国にいる\nお姫様のプリンなの\n魔物も虜にしちゃう\nすてきなプリンなの", "マホのプリン", "みらくるみやりん\nくるりんぱ～☆なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (21, 119, 3, "うおーん！ミヤコなんだか\n強くなった気がするの！\n困ったことがあればミヤコが\nまとめて面倒見てやるの！", 1, "カッコいいプリンを目指して\nワイルドなものをガンガン\n入れてみたの。きっと熱い\nプリンができるはずなの", "マコトのプリン", "ウルフェンバイトなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (22, 120, 3, "一口食べたら元気が\nあふれて止まらないの！\n気分がいいから、一曲\n踊りでも披露してやるの！", 1, "どっかの国でよくとれる\nゴーヤーに似てるやつを\nいれてみたの！ちょっと\n苦いらしいけど…", "カオリのプリン", "なんくるないさ～！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (23, 121, 3, "むむむ…なるほどなの\n上質な糖分をふんだんに\n使うことで、脳をより活性化\nできるからなの！", 1, "勘の鋭いやつが好きな食べ物を\nたくさん入れてみたの\n難しいこと考えるのにぴったり\nらしいけど、なんでなの？", "カスミのプリン", "ふふん。簡単な推理なの", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (24, 122, 3, "ミルクがとっても濃厚で\nほっぺたが落ちちゃうの～♪\nこのプリンからは牧場の…\n自然の息吹を感じるの！", 1, "搾りたての牛乳を\nたっぷり使ったプリンなの～\nマヒルに手伝ってもらって\nミヤコ直々に搾ってきたの！", "マヒルのプリン", "エリザベス～！なの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (25, 123, 3, "ほのかな甘さでありながら\nしっかりとした主張も\n感じさせる\n味わい深いプリンなの", 1, "マヒルからやさしいヤツだって\n聞いたの。やさしさを表現\nするために奥ゆかしい甘さに\n仕上げてみたの", "シオリのプリン", "私の好きな本…読んで\nもらえたらうれしいです…\nなの", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (26, 124, 3, "こ、これは…！口の中に入れた\n瞬間にふんわり溶けて\nなくなっちゃうの！\nその食感がやみつきなの！", 1, "牧場にいるヤツらしいの\n牛とは違うらしいの\nもふもふ気持ちいいらしいから\n食感にこだわって作ったの", "リマのプリン", "もふもふにしてあげるなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (27, 125, 3, "んむぅ…評価が難しい味なの…\nおいしいのはおいしいの…\nん～考えてたら…\n眠くなってきたの…", 0, "いっつも寝てるやつらしいの\nぐっすり眠れる薬草をたくさん\n入れてみたの。プリンとして\nおいしくなるかはわからないの", "リンのプリン", "めんどくさいな～なの…", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (28, 126, 3, "プ…プリンなのにクレープの味\nがするの。味もすごく普通なの\nでも…なんだかプリンの新しい\n扉を開けそうな気がするの…！", 1, "クレープ屋の真っ赤な人に\n教わったプリンなの\n作り方を丁寧に教えてくれて\nとっても優しい人だったの！", "ラビリスタのプリン", "プリンの権能を解放するの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (29, 127, 3, "とろける食感が絶品なの～♪\n食べるとなんだか幸せな\n気持ちになれるの…これが\n愛情ってやつなの？", 0, "お店に落ちてた謎のレシピの\nプリンなの。レシピの表紙には\n『お姉ちゃんの愛情たっぷり』\nって書いてあったの", "シズルのプリン", "お姉ちゃんパワー全開！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (30, 128, 3, "これで妹力？があがるらしいの。\n妹になればお兄ちゃんに\nプリンをたかり放題なの！\n最高なの～！", 1, "リノから作り方を教わったの！\nさすがクレープ屋で働いてる\nだけあって美味しそうなの！", "リノのプリン", "お兄ちゃん、プリンをよこすの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (31, 129, 3, "食べたら元気が湧いてくるの\nだからプリンのレシピのお礼に\nミヤコも人助けを手伝って\nやったの。ミヤコはえらいの！", 1, "プリンのレシピで悩んでたら\n通りすがりのおねーさんが\n一緒に考えてくれたプリンなの\nいいヤツもたまにはいるの～♪", "ヒヨリのプリン", "困った時はお互いさまさま！\nなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (32, 130, 3, "はっ…思わずお花畑が見えたの\n身も心も包まれるような\nとっても優しい味がするの\nこれは…まさに癒しなの～♪", 1, "ミヤコががんばって作った\nこだわりのプリンなの～\nプリンは癒しなの。だから優しい\n気持ちで丁寧に作ったの", "ユイのプリン", "フラワリングヒールなの～♪", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (33, 131, 3, "確かに完璧なプリンなの\nでも究極のプリンと呼ぶには\nまだまだ修行が必要なの…\nプリン作りは奥が深いの…！", 1, "究極のプリンを作るため\nミヤコは厳しい修行をしたの…\nその結果あって完成した\nクールで完璧なプリンなの！", "レイのプリン", "スラッシュテンペスト！なの。", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (34, 132, 3, "味にも素材にもこだわりが\nあるの。一流は妥協しないの\nもっと豪華に、もっとおいしく\nできるはず…", 1, "豪華で高級な\nお嬢様プリンなの\n中には宝石みたいな\n大きいイチゴを入れるの！", "アキノのプリン", "おーほっほほほ！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (35, 133, 3, "プリンは飲み物とも言うの\nぐいっていってみるの\n…ふわしゅわでとろけるの～！\n体に染みわたるの～", 1, "外はしっかり、中はふわとろの\nプリンにするの\n泡みたいなしゅわしゅわの\n生クリームも入れるの♪", "ユカリのプリン", "プリしゅわ最高～！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (36, 134, 3, "このプリンは焼きたてのうちに\n食べるのが一番なの…！\n熱いけどおいしくて\nうずうずしてきたの…！", 1, "餡子を入れて\nオーブンでこんがり焼くの\nたい…焼きプリンなの\n斬新なの！", "タマキのプリン", "にゃにゃにゃ！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (37, 135, 3, "プリンはいつでも手軽に\n食べられるのも魅力なの\nこれは食べ応えもあるから一つ\n食べればいっぱい動けるの", 0, "栄養バランスを考えて\n木の実をたくさん入れるの\nあれこれ忙しいときでも\n頼りになるプリンなの！", "ミフユのプリン", "効率全開！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (38, 136, 3, "このプリンを食べてから\nいい子になった気がするの\n大好きなプリンを泣いてる子に\nあげたの。いい気分なの", 1, "エルフの森で子どもにもらった\n薬草を使って作ったの\nこんな優しい味のプリンは\n初めてなの…", "ミサトのプリン", "あらあら～なの～♪", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (39, 137, 3, "あまいプリンが口の中で\nぽんぽん弾ける未知の味なの！\n今なら不思議な力で世界も\n救えそうなの！でも眠くなるの…", 1, "お昼寝でみた夢の中に\nでてきた不思議なプリンを\n作ってみたの。見てたらまた\n眠くなってきたの…", "ハツネのプリン", "スヤスヤ～…なの…", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (40, 138, 3, "知らないうちにはしっこに\n隠れちゃってたの。食べたら\nミヤコ、シノブたちに会いに\nいきたくなってきたの", 1, "お店のはしっこに一つだけ\n残ったおもちゃを見て思い\nついたの。他のプリンと一緒に\n置いておくと震えだすの", "アオイのプリン", "ぼっちは卒業なの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (41, 139, 3, "口の中に華やかな甘さが\n広がる…これがアイドルなの？\n急に歌って踊りたく\nなってきたの！", 1, "トップオブアイドルの\nプリンなの。キラキラした\nものを入れて、あつ～い\nオーブンで焼いてみたの", "ノゾミのプリン", "リズムあげるのー！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (42, 140, 3, "プリンの生地がとっても\nなめらかで最高の舌触りなの！\n精霊、ミヤコのプリンのために…", 1, "ミヤコにプリンをくれるすごく\nいいヤツのプリンなの\n精霊に呼びかけながら\n一生懸命かき混ぜたの", "チカのプリン", "風の加護を！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (43, 141, 3, "包装は食べるまでの手間が\n増えてめんどくさいの。でも\nそのめんどくささもプリンの\n味を引き立てるの", 1, "歌って踊って衣装も作れるヤツ\nのプリンなの。このプリンは\nきれいに包装するの。プリンを\n最高の形で着飾らせるの", "ツムギのプリン", "騎士さんのために\nしたんじゃありません！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (12, 142, 3, "んむっ！？\nく、口のなかでプリンの\nおいしさが大暴れなの！\n止まらないの！", 0, "プリンをくれないならどうでも\nいいヤツなの。でも横で\nいろいろ言ってきたから\nがんばって作ったの", "クリスティーナのプリン", "宴の始まりなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (44, 143, 3, "大人の味なの。今やミヤコは\nみんなの頼れる姐御なの！\n悪さするやつはミヤコが\n許さないの！", 1, "大人な甘さ控えめのプリンを\n作るの。試しにお魚を入れて\nみるの。プリンの可能性は\n無限大なの！", "ルカのプリン", "一刀両断、覚悟しな！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (45, 144, 3, "一口食べる度に味が変わって\n魔法みたいなの！\nもしかして全部食べたら\nミヤコも魔法少女になれるの？", 1, "サイカワサイツヨな\n魔法のプリンなの\n中身をカラフルにするの～\n甘いプリンは頭が冴えるの！", "ナナカのプリン", "きゅぴーん！キタコレ！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (46, 145, 3, "一口食べたら謎の組織に\n狙われたり、前世の記憶が蘇る\n気がするの～設定盛りすぎなの\nミヤコは、ミヤコは…", 1, "小難しい言葉をささやきながら\n作ったら魔力あふれるプリンが\n爆誕したの！でも、不思議と\nイタイタしいのはなぜなの～？", "アンナのプリン", "人呼んで、疾風のミヤコなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (47, 146, 3, "なんか普通のプリンよりも\nいい匂いがするの～…\nプリンのことがもっともっと\n好きになっちゃうの…", 1, "甘酸っぱい赤い木の実を\n切り刻んで入れるの\n甘くてちょっぴり刺激的な\nヤンデレのプリンなの", "エリコのプリン", "クスクス…クスクスクス…なの", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (48, 147, 3, "鼻に抜ける薬のにおいがアレ\nだけど大人っぽくて頭が\nよくなった気がするの。無性に\n実験したくてしかたないの", 1, "健康に気を遣うミヤコは\nプリンにお薬を入れてみたの～\nでもなんだか毒々しいから\n彩りにバラを添えてみたの～", "ミツキのプリン", "どんなプリンも\nミヤコの隻眼からは\n逃れられないの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (49, 148, 3, "ん～王道なプリンは\n甘くて安定したおいしさなの～\n思わず笑顔になっちゃうの\nにこにこなの～♪…はっ！", 1, "小さいけどしっかりした\n軍人のプリンなの\nちょっと固めにして\n砂糖はいっぱい入れるの", "モニカのプリン", "私は子どもではない！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (50, 149, 3, "このプリンを食べてから\n誰かにお仕えしなきゃ\nいけない気がするデースなの\nそれはショ、ショー…", 1, "オーエド町で手に入れた素材と\nトーゴクに伝わる術をかけて\nプリンを作るの。シュババ！\n忍法隠し味の術なの！", "ニノンのプリン", "ショーグン！　ミヤコと一緒に\n天下統一するデースなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (51, 150, 3, "カチカチに固めたせいで食感が\nプリンのようで\nプリンじゃないの…でもこの\nもどかしさが癖になるの…", 0, "オマエが持ってきた手錠を\nヒントに作ったプリンなの\nプリンが動けないように\nカチカチに固めたの", "クウカのプリン", "…ぐふふ、じゅるり～なの", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (52, 151, 3, "味も美しい以外の感想が\n出てこないの。ていうかこれを\n食べたミヤコも美しいの！\n鏡、鏡はどこなの！", 1, "とっても美しいプリンなの\n美しいものを手当たり次第\n入れたらすごいことになったの", "ユキのプリン", "あぁ、ミヤコはなんて美しいの～", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (53, 152, 3, "うん、やっぱりおいしく…\nん？あそこにいるのは\nアイツなの。あれ？\n体が勝手にアイツの方に…", 0, "知らないうちにお菓子が売れた\n時に思いついたプリンなの。\n作り方もよく覚えてない…\nけど、きっとおいしいの！", "アユミのプリン", "ジー…ってミヤコなにしてるの\nミヤコはストーカーじゃないの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (54, 153, 3, "見た目通り甘々で優しい味なの\nでも、レシピを見たら裏面に\n別の作り方が書いてあるの。\nこれだと激辛プリンに…", 0, "イタズラ好きの手下と一緒に\n作ったプリンなの。見た目は\nかわいいけど、作り方は\n意外と複雑なの～", "ミソギのプリン", "にひひ…イタズラの時間なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (55, 154, 3, "ん～、ふわふわの甘々なの！\nなんだか楽しくなって\n心も体もるんたったしてくるの", 0, "素直でやさしい手下と一緒に\n動物のぬいぐるみをいっぱい\n並べて作ったの", "ミミのプリン", "ぴょんぴょこぴょーん、なの♪", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (56, 155, 3, "ひんやりしてて暑い日でも\nおいしく食べられそうなの！\nん？これを買いたい大人が\nいる？それって…", 0, "幽霊を怖がっている手下と\n一緒に作ったプリンなの。\n小さいクセにきっちりしてて\nとってもかわいいプリンなの", "キョウカのプリン", "へんたいふしんしゃさんなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (57, 156, 3, "見て食べて楽しめる新機軸の\nプリンなの。ミヤコは幽霊\nだけど自分の足でランウェイを\n歩きたくなってきたの！", 1, "カリスマモデルなプリンなの\nモリモリにデコレーションして\nカリスマ感を演出したの", "スズナのプリン", "ハート狙い撃ち！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (58, 157, 3, "プ、プリンは全部ミヤコのもの\nなのに、なんだかこのプリンは\nいろんな人に教えたく\nなっちゃう不思議な味なの！", 0, "学校の先生をしてるヤツの\nプリンなの。お堅くしようと\nしたら、いつの間にか色っぽく\nなっちゃったの。なんでなの？", "イオのプリン", "授業を始めます♪なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (59, 158, 3, "ミヤコはプリンならどんなもの\nでも食べるの。でもカラメルを\nちょっとだけ足すの。\nちょっとだけなら…", 1, "少し背伸びしたおませな子を\n表現したプリンなの。あえて\n甘さ控えめなの。カラメルは\n後乗せできるから安心するの", "ミサキのプリン", "立派なレディ、なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (60, 159, 3, "味はすごいゴージャスなの！\nボスの風格があるの！\nビッグなミヤコに\nプリンを捧げるの！", 1, "謎に包まれたプリンができたの\n何か隠してるようなの…\nこれは危険なプリンなの！", "ホマレのプリン", "プリンを持ってこないと\nお仕置きだよ～☆なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (61, 160, 3, "最初の一口目が\nすごいインパクトなの！\n無性にケンカしたくなるの！\nプリンをよこせなの！", 1, "ワイルドな見た目なの！\nこれは期待できそうなの。\nきっと躍動感あふれる味なの！", "カヤのプリン", "たぎってきたの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (62, 161, 3, "見た目はアレだけど味はおいし\nいの…あと主張もはっきりして\nるの！やる気と自信だけは\n出てきたのうおおおーなの！", 0, "なんか見た目がパッとしないの\nこれほんとに大丈夫なの？\nなんか頼りないの…", "イノリのプリン", "下剋上、やってやるですなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (63, 162, 3, "むむむ…食べたら\nやる気が湧いてきたの！\nミヤコを邪魔するやつはみんな\nまとめてぶっ飛ばしてやるの～", 1, "天下の大悪党のプリンなの\nこれまでのジョーシキに\n捉われないプリンを\n作ってみたの～", "ムイミのプリン", "どけどけ～！なの～！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (64, 163, 3, "いつのまにか作ったの全部\n食べちゃったの。なんで\nプリンは分身しないの？\n無限に増えろなの！", 1, "いろんなものに変身したり\n分身したりできるヤツの\nプリンなの。型で同じプリンを\nたくさんたくさん作ったの", "ネネカのプリン", "ミラーミラー！なの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (65, 164, 3, "むぅ…認めたくないけど\nおいしいの…これを何個も\n作れるほどのお金を稼ぐのは\n大変なの…でもおいしいから…", 1, "金の亡者のプリンなの\n金にものを言わせて作って\nみたの。おばあちゃんの\nプリンと対極なの", "クレジッタのプリン", "プリンに忠誠を誓いますわ！\nなの！", 5);
INSERT INTO `v1_8085c2d30457ac4e480df3be16ff805b2cb89e605e10caae662f3c0ebd108101` VALUES (66, 165, 3, "手堅い…！手堅いの…！\n隙のないプリンなの！\n今のミヤコなら完璧な\n書類作成ができそうなの！", 1, "みんなお世話になるギルド\n管理協会職員のプリンなの\nお役所感を出すために手堅く\n王道に作ったの", "カリンのプリン", "ギルド管理協会へようこそ！\nなの！", 5);
